void NPGameManager_gameLoop(NPObject * self, SEL _cmd) {
    struct NPGameManager * _self = ((struct NPGameManager *)(self));
    {
        struct timespec sleepTime;
        sleepTime.tv_sec = 0;
        sleepTime.tv_nsec = 50000000;
        system("stty -icanon -echo");
        while (((struct NPGameManager *)(self))->state == GameStatePlaying || ((struct NPGameManager *)(self))->state == GameStatePaused) {
            {
                if (((struct NPGameManager *)(self))->state == GameStatePlaying) {
                    {
                        ((struct nupa_NPGameManager_vtable *)self->isa->vtable)->processInput(self, __nupa_sel_processInput);
                        ((struct nupa_NPGameManager_vtable *)self->isa->vtable)->update(self, __nupa_sel_update);
                        ((struct nupa_NPGameManager_vtable *)self->isa->vtable)->checkCollisions(self, __nupa_sel_checkCollisions);
                    }
                }
                ((struct nupa_NPGameManager_vtable *)self->isa->vtable)->render(self, __nupa_sel_render);
                if (((struct NPGameManager *)(self))->state == GameStateGameOver) {
                    {
                        ((struct nupa_NPGameManager_vtable *)self->isa->vtable)->drawGameOver(self, __nupa_sel_drawGameOver);
                        break;
                    }
                }
                if (((struct NPGameManager *)(self))->state == GameStateVictory) {
                    {
                        ((struct nupa_NPGameManager_vtable *)self->isa->vtable)->drawVictory(self, __nupa_sel_drawVictory);
                        break;
                    }
                }
                nanosleep(&sleepTime, NULL);
                ((struct NPGameManager *)(self))->frameCount++;
            }
        }
        system("stty icanon echo");
        if (((struct NPGameManager *)(self))->state == GameStateGameOver || ((struct NPGameManager *)(self))->state == GameStateVictory) {
            {
                printf("\n\n%s按 [Enter] 返回主菜单...%s", COLOR_CYAN, COLOR_RESET);
                char input[10];
                fgets(input, sizeof(input), stdin);
                ((struct NPGameManager *)(self))->state = GameStateMenu;
                ((struct nupa_NPGameManager_vtable *)self->isa->vtable)->showMenu(self, __nupa_sel_showMenu);
            }
        }
    }
}

